from __future__ import annotations
import base64
from pathlib import Path

FILES = {
'engine/ai/strategy_acceptance.py': '',
'ui/strategy_lab_page.py': '',
'tests/test_strategy_acceptance_10_14c.py': '',
}

def main():
    root=Path(__file__).resolve().parent
    required=root/'engine'/'ai'/'walk_forward_lab.py'
    if not required.exists():
        raise SystemExit('Hata: Bu paket proje ana klasöründe çalıştırılmalıdır.')
    for rel, encoded in FILES.items():
        target=root/rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(encoded))
        print(f'Yazıldı: {rel}')
    print('Sprint 10.14C uygulandı.')

if __name__=='__main__':
    main()
